// with a validator is refused, since there is nothing for the validator to
// check, and so is one that only a create could write. A create refuses a
// mutation holding an expression at all.
func (m *Mutation) SetFieldExpr(name string, expr sql.Querier) error {
	if expr == nil {
		return fmt.Errorf("no expression for field %s", name)
	}
	if m.op.Is(ent.OpCreate) {
		return fmt.Errorf("field %s cannot be assigned an expression: a create writes values, and an expression is written only by an update", name)
	}
	switch name {
	case FieldTenantId:
		m.ResetTenantId()
	case FieldActorId:
		m.ResetActorId()
	case FieldTraceId:
		m.ResetTraceId()
	case FieldAction:
		m.ResetAction()
	case FieldObjectId:
		m.ResetObjectId()
	case FieldPatch:
		m.ResetPatch()
	case FieldDateCreated:
		return fmt.Errorf("field %s cannot be assigned an expression: it is immutable, and an expression is written only by an update", name)
	case FieldActorTenantId:
		m.ResetActorTenantId()
	case FieldValue:
		m.ResetValue()
	case FieldCounterpartTenantId:
		m.ResetCounterpartTenantId()
	case FieldDomain:
		m.ResetDomain()
	case FieldFields:
		m.ResetFields()
	case FieldDigest:
		m.ResetDigest()
	case FieldDigestFields:
		m.ResetDigestFields()
	default:
		return fmt.Errorf("unknown Audit field %s", name)
	}
	if m.exprs == nil {
		m.exprs = make(map[string]sql.Querier)
	}
	m.exprs[name] = expr
	return nil
}

// FieldExpr returns the expression the field with the given name was assigned
// by SetFieldExpr. The second return value reports whether it was.
func (m *Mutation) FieldExpr(name string) (sql.Querier, bool) {
	e, ok := m.exprs[name]
	return e, ok
}

// ExprFields returns the fields that were assigned an expression by
// SetFieldExpr.
func (m *Mutation) ExprFields() []string {
	var fields []string
	if _, ok := m.exprs[FieldTenantId]; ok {
		fields = append(fields, FieldTenantId)
	}
	if _, ok := m.exprs[FieldActorId]; ok {
		fields = append(fields, FieldActorId)
	}
	if _, ok := m.exprs[FieldTraceId]; ok {
		fields = append(fields, FieldTraceId)
	}
	if _, ok := m.exprs[FieldAction]; ok {
		fields = append(fields, FieldAction)
	}
	if _, ok := m.exprs[FieldObjectId]; ok {
		fields = append(fields, FieldObjectId)
	}
	if _, ok := m.exprs[FieldPatch]; ok {
		fields = append(fields, FieldPatch)
	}
	if _, ok := m.exprs[FieldActorTenantId]; ok {
		fields = append(fields, FieldActorTenantId)
	}
	if _, ok := m.exprs[FieldValue]; ok {
		fields = append(fields, FieldValue)
	}
	if _, ok := m.exprs[FieldCounterpartTenantId]; ok {
		fields = append(fields, FieldCounterpartTenantId)
	}
	if _, ok := m.exprs[FieldDomain]; ok {
		fields = append(fields, FieldDomain)
	}
	if _, ok := m.exprs[FieldFields]; ok {
		fields = append(fields, FieldFields)
	}
	if _, ok := m.exprs[FieldDigest]; ok {
		fields = append(fields, FieldDigest)
	}
	if _, ok := m.exprs[FieldDigestFields]; ok {
		fields = append(fields, FieldDigestFields)
	}
	return fields
}

// AddedFields returns all numeric fields that were incremented/decremented during
// this mutation.
func (m *Mutation) AddedFields() []string {
	var fields []string
	if m.adddomain != nil {
		fields = append(fields, FieldDomain)
	}
	return fields
}

// AddedField returns the numeric value that was incremented/decremented on a field
// with the given name. The second boolean return value indicates that this field
// was not set, or was not defined in the schema.
func (m *Mutation) AddedField(name string) (ent.Value, bool) {
	switch name {
	case FieldDomain:
		return m.AddedDomain()
	}
	return nil, false
}

// AddField adds the value to the field with the given name. It returns an error if
// the field is not defined in the schema, or if the type mismatched the field
// type.
func (m *Mutation) AddField(name string, value ent.Value) error {
	switch name {
	case FieldDomain:
		v, ok := value.(int32)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.AddDomain(v)
		return nil
	}
	return fmt.Errorf("unknown Audit numeric field %s", name)
}

// ClearedFields returns all nullable fields that were cleared during this
// mutation.
func (m *Mutation) ClearedFields() []string {
	var fields []string
	if m.FieldCleared(FieldDateCreated) {
		fields = append(fields, FieldDateCreated)
	}
	if m.FieldCleared(FieldCounterpartTenantId) {
		fields = append(fields, FieldCounterpartTenantId)
	}
	if m.FieldCleared(FieldDomain) {
		fields = append(fields, FieldDomain)
	}
	if m.FieldCleared(FieldFields) {
		fields = append(fields, FieldFields)
	}
	if m.FieldCleared(FieldDigest) {
		fields = append(fields, FieldDigest)
	}
	if m.FieldCleared(FieldDigestFields) {
		fields = append(fields, FieldDigestFields)
	}
	return fields
}

// FieldCleared returns a boolean indicating if a field with the given name was
// cleared in this mutation.
func (m *Mutation) FieldCleared(name string) bool {
	_, ok := m.clearedFields[name]
	return ok
}

// ClearField clears the value of the field with the given name. It returns an
// error if the field is not defined in the schema.
func (m *Mutation) ClearField(name string) error {
	switch name {
	case FieldDateCreated:
		m.ClearDateCreated()
		return nil
	case FieldCounterpartTenantId:
		m.ClearCounterpartTenantId()
		return nil
	case FieldDomain:
		m.ClearDomain()
		return nil
	case FieldFields:
		m.ClearFields()
		return nil
	case FieldDigest:
		m.ClearDigest()
		return nil
	case FieldDigestFields:
		m.ClearDigestFields()
		return nil
	}
	return fmt.Errorf("unknown Audit nullable field %s", name)
}

// ResetField resets all changes in the mutation for the field with the given name.
// It returns an error if the field is not defined in the schema.
func (m *Mutation) ResetField(name string) error {
	switch name {
	case FieldTenantId:
		m.ResetTenantId()
		return nil
	case FieldActorId:
		m.ResetActorId()
		return nil
	case FieldTraceId:
		m.ResetTraceId()
		return nil
	case FieldAction:
		m.ResetAction()
		return nil
	case FieldObjectId:
		m.ResetObjectId()
		return nil
	case FieldPatch:
		m.ResetPatch()
		return nil
	case FieldDateCreated:
		m.ResetDateCreated()
		return nil
	case FieldActorTenantId:
		m.ResetActorTenantId()
		return nil
	case FieldValue:
		m.ResetValue()
		return nil
	case FieldCounterpartTenantId:
		m.ResetCounterpartTenantId()
		return nil
	case FieldDomain:
		m.ResetDomain()
		return nil
	case FieldFields:
		m.ResetFields()
		return nil
	case FieldDigest:
		m.ResetDigest()
		return nil
	case FieldDigestFields:
		m.ResetDigestFields()
		return nil
	}
	return fmt.Errorf("unknown Audit field %s", name)
}

// AddedEdges returns all edge names that were set/added in this mutation.
func (m *Mutation) AddedEdges() []string {
	edges := make([]string, 0, 0)
	return edges
}

// AddedIds returns all Ids (to other nodes) that were added for the given edge
// name in this mutation.
func (m *Mutation) AddedIds(name string) []ent.Value {
	return nil
}

// RemovedEdges returns all edge names that were removed in this mutation.
func (m *Mutation) RemovedEdges() []string {
	edges := make([]string, 0, 0)
	return edges
}

// RemovedIds returns all Ids (to other nodes) that were removed for the edge with
// the given name in this mutation.
func (m *Mutation) RemovedIds(name string) []ent.Value {
	return nil
}

// ClearedEdges returns all edge names that were cleared in this mutation.
func (m *Mutation) ClearedEdges() []string {
	edges := make([]string, 0, 0)
	return edges
}

// EdgeCleared returns a boolean which indicates if the edge with the given name
// was cleared in this mutation.
func (m *Mutation) EdgeCleared(name string) bool {
	return false
}

// ClearEdge clears the value of the edge with the given name. It returns an error
// if that edge is not defined in the schema.
func (m *Mutation) ClearEdge(name string) error {
	return fmt.Errorf("unknown Audit unique edge %s", name)
}

// ResetEdge resets all changes to the edge with the given name in this mutation.
// It returns an error if the edge is not defined in the schema.
func (m *Mutation) ResetEdge(name string) error {
	return fmt.Errorf("unknown Audit edge %s", name)
}
